function renderConfig(){return `<div class="page-head"><div><div class="eyebrow">Personalización y datos</div><h1>Ajustes</h1><p>Adapta las categorías a la forma de trabajar de la banda y guarda copias de seguridad antes de hacer cambios importantes.</p></div></div><div class="grid config-grid"><section class="card setting-card"><h2>Tipos de actuación</h2><p>Las categorías aparecen como opciones al crear o editar una actuación. Puedes añadir las que necesitéis o eliminar las que no uséis.</p><form id="categoryForm" class="add-category-row"><input id="newCategory" maxlength="40" placeholder="Ej. Diana, certamen, concierto…" required><button class="btn btn-primary" type="submit">Añadir</button></form><div class="category-list">${state.categories.map(c=>`<span class="category-chip">${esc(c)}<button data-action="remove-category" data-value="${esc(c)}" aria-label="Eliminar ${esc(c)}">×</button></span>`).join('')}</div><div class="footnote">Si una categoría ya se está usando, eliminarla no borra las actuaciones; esas fichas conservarán la categoría hasta que las edites.</div></section><section class="card setting-card"><h2>Copias y portabilidad</h2><p>Los cambios se conservan en este dispositivo. En Netlify, al iniciar sesión, también puedes sincronizar la copia compartida para usar los mismos datos en otros dispositivos.</p><div class="backup-row"><div><strong>Exportar copia completa</strong><span>Repertorio, autores, categorías y actuaciones.</span></div><button class="btn btn-soft btn-small" data-action="export-json">Descargar JSON</button></div><div class="backup-row"><div><strong>Importar una copia</strong><span>Reemplaza los datos actuales por los del archivo elegido.</span></div><button class="btn btn-soft btn-small" data-action="import-json">Elegir archivo</button><input class="hidden" type="file" id="importFile" accept="application/json,.json"></div><div class="backup-row"><div><strong>Exportar actuaciones a CSV</strong><span>Una fila por cada marcha interpretada, para Excel.</span></div><button class="btn btn-soft btn-small" data-action="export-csv">Descargar CSV</button></div><div class="backup-row"><div><strong>Restaurar datos del Excel original</strong><span>Vuelve al estado con el que se entrega esta demo.</span></div><button class="btn btn-danger btn-small" data-action="reset">Restaurar</button></div></section><section class="card setting-card"><h2>Cómo funciona el recuento</h2><p>El número de interpretaciones se calcula contando las marchas vinculadas a todas las actuaciones registradas. Puedes filtrar los datos en las pantallas de resumen y actuaciones.</p><div class="event-tags"><span class="pill red">Cálculo automático</span><span class="pill">Sin fórmulas de Excel</span><span class="pill gold">Editable</span></div></section><section class="card setting-card"><h2>Estado de esta versión</h2><p>Los datos se guardan en este dispositivo y, cuando hay una sesión activa de Netlify, pueden sincronizarse con la nube.</p><div class="backup-row"><div><strong>Repertorio</strong><span>${state.repertoire.length} marchas definidas</span></div><span class="pill">Local / nube</span></div><div class="backup-row"><div><strong>Actuaciones</strong><span>${state.events.length} fichas · ${totalPlays()} interpretaciones</span></div><span class="pill">Local / nube</span></div><div class="footnote">La copia de este dispositivo se mantiene en el navegador. La sincronización compartida depende de que la sesión de Netlify esté iniciada y el guardado en la nube se complete.</div></section></div>`}
function render(){document.getElementById('topTitle').textContent=({dashboard:'Resumen general',actuaciones:'Actuaciones y días de toque',repertorio:'Repertorio musical',informes:'Informes y PDF',configuracion:'Ajustes y personalización'})[page]||'Registro de marchas';document.getElementById('dateToday').textContent=new Intl.DateTimeFormat('es-ES',{weekday:'short',day:'numeric',month:'short'}).format(new Date());document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const root=document.getElementById('content');root.innerHTML=page==='dashboard'?renderDashboard():page==='actuaciones'?renderActuaciones():page==='repertorio'?renderRepertorio():page==='informes'?renderReports():renderConfig()}
const bmmScrollLocks = new Set();
let bmmScrollPosition = 0, bmmPreviousBodyStyle = '', bmmModalTrigger = null, bmmLabelSequence = 0;
function bmmLockScroll(owner){
  if(bmmScrollLocks.has(owner))return;
  if(!bmmScrollLocks.size){
    bmmScrollPosition=window.scrollY;
    bmmPreviousBodyStyle=document.body.getAttribute('style')||'';
    Object.assign(document.body.style,{position:'fixed',top:`-${bmmScrollPosition}px`,left:'0',right:'0',width:'100%',overflow:'hidden'});
  }
  bmmScrollLocks.add(owner);
}
function bmmUnlockScroll(owner){
  if(!bmmScrollLocks.delete(owner)||bmmScrollLocks.size)return;
  document.body.setAttribute('style',bmmPreviousBodyStyle);
  window.scrollTo({top:bmmScrollPosition,left:0,behavior:'instant'});
}
function bmmFocusable(container){
  return [...container.querySelectorAll('button, a[href], input:not([type="hidden"]), select, textarea, [tabindex]')].filter(control=>!control.disabled&&control.tabIndex>=0&&!control.closest('[inert]')&&control.getClientRects().length);
}
function bmmModalSnapshot(){
  return JSON.stringify([...document.querySelectorAll('#modal form [name]')].map(control=>[control.name,control.type==='checkbox'||control.type==='radio'?control.checked:control.value]));
}
function bmmAssociateLabels(container){
  container.querySelectorAll('label:not([for])').forEach(label=>{
    if(label.querySelector('input,select,textarea'))return;
    const field=label.closest('.field');
    const control=field?.querySelector('input:not([type="hidden"]),select,textarea');
    if(!control)return;
    if(!control.id)control.id=`bmm-field-${container.id||'content'}-${++bmmLabelSequence}`;
    label.htmlFor=control.id;
  });
  container.querySelectorAll('input:not([type="hidden"]),select,textarea').forEach(control=>{
    if(control.labels?.length||control.hasAttribute('aria-label')||control.hasAttribute('aria-labelledby'))return;
    const names={repStyle:'Estilo musical',repHistoryFilter:'Historial de interpretaciones',dashPeriod:'Periodo del resumen',actYear:'Año de las actuaciones',actCategory:'Categoría de las actuaciones',reportYear:'Año del informe',reportGroup:'Grupo del informe',reportCategory:'Categoría del informe',reportFrom:'Fecha inicial del informe',reportTo:'Fecha final del informe'};
    const label=names[control.id]||control.getAttribute('placeholder')||control.options?.[0]?.textContent||control.name;
    if(label)control.setAttribute('aria-label',label);
  });
}
function openModal(title,desc,body,footer,small=false){
  const back=document.getElementById('modalBackdrop'),modal=document.getElementById('modal');
  if(!back.classList.contains('open'))bmmModalTrigger=document.activeElement;
  window.bmmCloseDrawer?.(false);
  modal.className='modal'+(small?' small':'');
  modal.innerHTML=`<div class="modal-header"><div><h2 id="bmmModalTitle">${esc(title)}</h2><p id="bmmModalDescription">${esc(desc)}</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Cerrar">×</button></div><div class="modal-content">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;
  modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-labelledby','bmmModalTitle');modal.setAttribute('aria-describedby','bmmModalDescription');modal.tabIndex=-1;
  back.inert=false;back.classList.add('open');back.setAttribute('aria-hidden','false');
  document.querySelector('.app').inert=true;
  document.querySelector('.bmm-floating-save')?.setAttribute('inert','');
  bmmLockScroll('modal');bmmAssociateLabels(modal);
  modal.dataset.dirty='false';
  queueMicrotask(()=>{modal.dataset.initialSnapshot=bmmModalSnapshot();});
  setTimeout(()=>{if(back.classList.contains('open'))(bmmFocusable(modal).find(control=>control.matches('input:not([type="hidden"]),select,textarea'))||modal).focus({preventScroll:true});},0);
}
function requestModalClose(){
  const modal=document.getElementById('modal');
  if(!document.getElementById('modalBackdrop').classList.contains('open'))return;
  if((modal.dataset.dirty==='true'||(modal.querySelector('form')&&modal.dataset.initialSnapshot!==bmmModalSnapshot()))&&!confirm('Hay cambios sin guardar. ¿Quieres cerrar y descartar esta edición?'))return;
  closeModal();
}
function closeModal(){
  const back=document.getElementById('modalBackdrop');
  if(!back.classList.contains('open'))return;
  back.classList.remove('open');back.setAttribute('aria-hidden','true');back.inert=true;
  document.querySelector('.app').inert=false;
  document.querySelector('.bmm-floating-save')?.removeAttribute('inert');
  bmmUnlockScroll('modal');currentEditEvent=null;currentEditMarch=null;
  if(bmmModalTrigger?.isConnected&&!bmmModalTrigger.closest('[inert]'))bmmModalTrigger.focus({preventScroll:true});
  else{const content=document.getElementById('content');content.tabIndex=-1;content.focus({preventScroll:true});}
}
document.addEventListener('keydown',event=>{
  const modal=document.getElementById('modal');
  if(event.key!=='Tab'||!document.getElementById('modalBackdrop').classList.contains('open'))return;
  const controls=bmmFocusable(modal),first=controls[0],last=controls[controls.length-1];
  if(!first){event.preventDefault();modal.focus();return;}
  if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last.focus();}
  else if(!event.shiftKey&&(document.activeElement===last||!modal.contains(document.activeElement))){event.preventDefault();first.focus();}
},true);
document.addEventListener('input',event=>{if(event.target.closest('#modal form'))document.getElementById('modal').dataset.dirty='true';},true);
document.addEventListener('change',event=>{if(event.target.closest('#modal form'))document.getElementById('modal').dataset.dirty='true';},true);
document.getElementById('modalBackdrop').inert=true;
function marchRowHtml(p={}){const options=state.repertoire.slice().sort((a,b)=>a.name.localeCompare(b.name,'es')).map(m=>`<option value="${esc(m.id)}" ${p.marchId===m.id?'selected':''}>${esc(m.name)}${m.author?' · '+esc(m.author):''}</option>`).join('');return `<div class="march-row"><div class="march-row-top"><span>Marcha de la actuación</span><div class="march-row-controls"><button type="button" class="icon-btn march-row-control" data-action="move-march-up" title="Subir una posición" aria-label="Subir marcha">↑</button><button type="button" class="icon-btn march-row-control" data-action="duplicate-march-row" title="Repetir esta marcha" aria-label="Repetir esta marcha">⧉</button><button type="button" class="icon-btn march-row-control" data-action="move-march-down" title="Bajar una posición" aria-label="Bajar marcha">↓</button><button type="button" class="icon-btn march-row-control march-row-remove" data-action="remove-march-row" title="Quitar esta aparición" aria-label="Quitar esta aparición">×</button></div></div><div class="march-row-fields"><div class="field"><label>Marcha del repertorio *</label><select name="marchId"><option value="">Selecciona una marcha…</option>${options}</select></div><div class="field"><label>Momento / ubicación</label><input name="location" value="${esc(p.location||'')}" placeholder="Ej. salida, plaza…"></div><div class="field"><label>Orden</label><input name="order" type="number" min="1" value="${esc(p.order||'')}" placeholder="1"></div><div class="field"><label>Hora de interpretación (opcional)</label><input name="startTime" type="time" value="${esc(p.startTime||'')}"></div><div class="field"><label>Duración (min, opcional)</label><input name="duration" type="number" min="0" max="240" value="${esc(p.duration||'')}" placeholder="Ej. 4"></div><div class="field full"><label>Observaciones</label><input name="notes" value="${esc(p.notes||'')}" placeholder="Ej. pasacalles, bis…"></div></div></div>`}
function quickMarchPicker(){const options=state.repertoire.slice().sort((a,b)=>a.name.localeCompare(b.name,'es')).map(m=>`<label class="quick-march-option" data-quick-name="${esc((m.name+' '+m.author).toLocaleLowerCase('es'))}"><input type="checkbox" name="quickMarchIds" value="${esc(m.id)}"><span><strong>${esc(m.name)}</strong>${m.author?`<br><span style="color:var(--muted)">${esc(m.author)}</span>`:''}</span></label>`).join('');return `<details class="quick-pick"><summary>＋ Seleccionar varias marchas de una vez</summary><div class="quick-pick-tools"><input type="search" id="quickMarchSearch" placeholder="Buscar marchas o autores…"><button type="button" class="btn btn-soft btn-small" data-action="select-visible-marches">Seleccionar visibles</button></div><div class="quick-march-options">${options}</div><div class="footnote">La selección múltiple añade cada título una vez. Para repetir una marcha dentro de la misma actuación, usa el botón ⧉ de su fila detallada.</div></details>`}
function eventForm(e){currentEditEvent=e?.id||null;const isEdit=!!e;const groups=[...new Set(state.events.map(x=>(x.group||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'));const body=`<form id="eventForm"><input type="hidden" name="eventId" value="${esc(e?.id||'')}"><div class="form-grid"><div class="field"><label>Fecha de actuación *</label><input name="date" type="date" required value="${esc(e?.date||new Date().toISOString().slice(0,10))}"></div><div class="field"><label>Hora (opcional)</label><input name="time" type="time" value="${esc(e?.time||'')}"></div><div class="field"><label>Tipo / categoría</label><select name="category">${state.categories.map(c=>`<option value="${esc(c)}" ${(e?.category||state.categories[0])===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Grupo / campaña</label><input name="group" list="eventGroups" maxlength="80" value="${esc(e?.group||'')}" placeholder="Ej. Semana Santa"><datalist id="eventGroups">${groups.map(g=>`<option value="${esc(g)}">`).join('')}</datalist></div><div class="field full"><label>Nombre del evento / hermandad *</label><input name="name" required maxlength="120" value="${esc(e?.name||'')}" placeholder="Ej. Domingo de Ramos"></div><div class="field full"><label>Localidad / lugar (opcional)</label><input name="locality" maxlength="100" value="${esc(e?.locality||'')}" placeholder="Ej. Arjonilla"></div><div class="field full"><label>Notas generales (opcional)</label><textarea name="eventNotes" placeholder="Información general de la actuación…">${esc(e?.notes||'')}</textarea></div></div>${quickMarchPicker()}<div class="marches-head"><h3>Marchas interpretadas <span class="pill">Opcional</span></h3><button type="button" class="btn btn-soft btn-small" data-action="add-march-row">＋ Añadir marcha individual</button></div><div id="marchRows">${(e?.marches?.length?[...e.marches].sort((a,b)=>(+a.order||0)-(+b.order||0)): [{}]).map(marchRowHtml).join('')}</div></form>`;openModal(isEdit?'Editar actuación':'Nueva actuación',isEdit?'Modifica los datos del día y las marchas interpretadas.':'Guarda el evento con fecha, hora y grupo; selecciona muchas marchas en un solo paso.',body,`<button class="btn btn-soft" type="button" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit" form="eventForm">${isEdit?'Guardar cambios':'Guardar actuación'}</button>`)}

function marchForm(m){currentEditMarch=m?.id||null;const body=`<form id="marchForm"><input type="hidden" name="marchId" value="${esc(m?.id||'')}"><div class="form-grid"><div class="field full"><label>Nombre de la marcha *</label><input name="name" required maxlength="120" value="${esc(m?.name||'')}" placeholder="Nombre tal y como aparece en el repertorio"></div><div class="field full"><label>Autor / compositor</label><input name="author" maxlength="120" value="${esc(m?.author||'')}" placeholder="Nombre del compositor"></div><div class="field full"><label>Estilo / tipo</label><input name="style" maxlength="80" value="${esc(m?.style||'')}" placeholder="Ej. marcha procesional, himno…"></div></div></form>`;openModal(m?'Editar marcha':'Añadir marcha','Completa la información de la pieza del repertorio.',body,`<button class="btn btn-soft" type="button" data-action="close-modal">Cancelar</button><button class="btn btn-primary" form="marchForm" type="submit">${m?'Guardar cambios':'Añadir al repertorio'}</button>`,true)}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportJson(){download('santa-cecilia-copia-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json;charset=utf-8');showToast('Copia JSON preparada para descargar')}
function csvCell(x){return '"'+String(x??'').replace(/"/g,'""')+'"'}
function exportCsv(){const rows=[['Fecha','Hora','Grupo','Actuación','Categoría','Localidad','Marcha','Autor','Momento / ubicación','Orden','Observaciones']];for(const e of [...state.events].sort((a,b)=>a.date.localeCompare(b.date))){if(!e.marches?.length)rows.push([e.date,e.time,e.group,e.name,e.category,e.locality,'','','','','']);else for(const p of e.marches){const m=getMarch(p.marchId);rows.push([e.date,e.time,e.group,e.name,e.category,e.locality,m?.name,m?.author,p.location,p.order,p.notes])}}download('santa-cecilia-actuaciones.csv','\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');showToast('CSV preparado para abrir en Excel')}
function handleAction(el){const a=el.dataset.action,id=el.dataset.id;
 if(a==='export-report-pdf'){printReport();return}
 if(a==='select-all-report'){getReportFilteredEvents().forEach(e=>selectedReportEvents.add(e.id));render();return}
 if(a==='clear-report-selection'){selectedReportEvents.clear();render();return}
 if(a==='clear-report-filters'){reportSearch='';reportYear='all';reportGroup='all';reportCategory='all';reportFrom='';reportTo='';selectedReportEvents.clear();render();return}
 if(a==='select-visible-marches'){document.querySelectorAll('.quick-march-option').forEach(row=>{if(!row.classList.contains('quick-hidden')){const cb=row.querySelector('input');if(cb)cb.checked=true}});return}
 if(a==='close-modal'){requestModalClose();return}
 if(a==='add-event'){eventForm(null);return}
 if(a==='edit-event'){const e=state.events.find(x=>x.id===id);if(e)eventForm(e);return}
 if(a==='delete-event'){const e=state.events.find(x=>x.id===id);if(e&&confirm(`¿Eliminar la actuación «${e.name}» y sus ${e.marches.length} marchas registradas?`)){state.events=state.events.filter(x=>x.id!==id);save('Actuación eliminada');}return}
 if(a==='add-march'){marchForm(null);return}
 if(a==='edit-march'){const m=getMarch(id);if(m)marchForm(m);return}
 if(a==='delete-march'){const m=getMarch(id);if(!m)return;const used=state.events.reduce((n,e)=>n+(e.marches||[]).filter(p=>p.marchId===id).length,0);const msg=used?`«${m.name}» figura ${used} vez/veces en actuaciones. Si la eliminas, también se retirarán esos registros históricos. ¿Continuar?`:`¿Eliminar «${m.name}» del repertorio?`;if(confirm(msg)){state.repertoire=state.repertoire.filter(x=>x.id!==id);state.events.forEach(e=>e.marches=(e.marches||[]).filter(p=>p.marchId!==id));save('Marcha eliminada del repertorio y del historial');}return}
 if(a==='add-march-row'){const wrap=document.getElementById('marchRows');if(wrap){wrap.insertAdjacentHTML('beforeend',marchRowHtml({order:wrap.querySelectorAll('.march-row').length+1}));wrap.lastElementChild?.querySelector('select')?.focus()}return}
 if(a==='remove-march-row'){const row=el.closest('.march-row');const wrap=document.getElementById('marchRows');if(row&&wrap){if(wrap.querySelectorAll('.march-row').length===1){row.querySelector('select').value='';row.querySelectorAll('input').forEach(i=>i.value='')}else row.remove()}return}
 if(a==='export-json'){exportJson();return}
 if(a==='export-csv'){exportCsv();return}
 if(a==='import-json'){document.getElementById('importFile')?.click();return}
 if(a==='reset'){if(confirm('Esto reemplazará los datos de este navegador por los incluidos en el Excel original. Antes, exporta una copia si quieres conservar tus cambios. ¿Restaurar?')){state=clone(SEED);save('Datos originales restaurados');setPage('dashboard')}return}
 if(a==='remove-category'){const v=el.dataset.value;if(state.categories.length<2){showToast('Debe quedar al menos una categoría.',true);return}if(confirm(`¿Quitar la categoría «${v}» de las opciones?`)){state.categories=state.categories.filter(c=>c!==v);save('Categoría retirada de las opciones')}return}
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-page]');if(!target)return;if(target.dataset.page){setPage(target.dataset.page);return}handleAction(target)});
document.getElementById('modalBackdrop').addEventListener('click',event=>{if(event.target.id==='modalBackdrop')requestModalClose();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.getElementById('modalBackdrop').classList.contains('open')){event.preventDefault();requestModalClose();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-report-event]')){if(!reportSelectionTouched){selectedReportEvents=new Set(getReportFilteredEvents().map(x=>x.id));reportSelectionTouched=true;}if(e.target.checked)selectedReportEvents.add(e.target.dataset.reportEvent);else selectedReportEvents.delete(e.target.dataset.reportEvent);const el=document.querySelector('.report-tally .pill:last-child');if(el)el.textContent=selectedReportEvents.size+' seleccionados a mano';const btns=[...document.querySelectorAll('[data-action="export-report-pdf"]')];btns.forEach(b=>{b.textContent='Generar PDF A4 ('+selectedReportEvents.size+')'});return}const id=e.target.id;if(id==='reportYear'){reportYear=e.target.value;render()}if(id==='reportGroup'){reportGroup=e.target.value;render()}if(id==='reportCategory'){reportCategory=e.target.value;render()}if(id==='reportFrom'){reportFrom=e.target.value;render()}if(id==='reportTo'){reportTo=e.target.value;render()}if(id==='dashPeriod'){dashPeriod=e.target.value;render()}if(id==='actYear'){actYear=e.target.value;render()}if(id==='actCategory'){actCategory=e.target.value;render()}if(id==='repStyle'){repStyle=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='quickMarchSearch'){quickMarchSearch=e.target.value.toLocaleLowerCase('es');document.querySelectorAll('.quick-march-option').forEach(row=>{const show=row.dataset.quickName.includes(quickMarchSearch);row.classList.toggle('quick-hidden',!show);row.style.display=show?(row.classList.contains('bmm-quick-march-v178')?'grid':'flex'):'none'});}if(e.target.id==='reportSearch'){reportSearch=e.target.value;const pos=e.target.selectionStart;render();const i=document.getElementById('reportSearch');i?.focus();i?.setSelectionRange(pos,pos)}if(e.target.id==='actSearch'){actSearch=e.target.value;const pos=e.target.selectionStart;render();const i=document.getElementById('actSearch');i?.focus();i?.setSelectionRange(pos,pos)}if(e.target.id==='repSearch'){repSearch=e.target.value;const pos=e.target.selectionStart;render();const i=document.getElementById('repSearch');i?.focus();i?.setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{if(e.target.id==='eventForm'){e.preventDefault();const f=new FormData(e.target);const id=f.get('eventId');const name=String(f.get('name')||'').trim();if(!name){showToast('Escribe el nombre de la actuación.',true);return}const old=state.events.find(x=>x.id===id);const marches=[...e.target.querySelectorAll('.march-row')].map((row,i)=>{const g=n=>row.querySelector(`[name="${n}"]`)?.value?.trim()||'';return {id:uid('perf'),marchId:g('marchId'),sourceTitle:g('sourceTitle'),sourceStop:parseInt(g('sourceStop'),10)||parseInt(g('order'),10)||i+1,location:g('location'),order:parseInt(g('order'),10)||i+1,startTime:g('startTime'),duration:g('duration'),notes:g('notes')}}).filter(p=>p.marchId);[...e.target.querySelectorAll('input[name="quickMarchIds"]:checked')].forEach(ch=>{const qtyNode=[...e.target.querySelectorAll('[data-quick-count]')].find(n=>n.dataset.marchId===ch.value);const qty=Math.max(1,Math.min(10,parseInt(qtyNode?.value,10)||1));for(let n=0;n<qty;n++)marches.push({id:uid('perf'),marchId:ch.value,location:'',order:marches.length+1,notes:''});});marches.forEach((p,i)=>{if(!p.order||p.order<1)p.order=i+1});const obj={id:id||uid('event'),date:String(f.get('date')||''),time:String(f.get('time')||''),group:String(f.get('group')||'').trim(),name,category:String(f.get('category')||'Otro'),locality:String(f.get('locality')||'').trim(),notes:String(f.get('eventNotes')||'').trim(),marches};if(old)state.events=state.events.map(x=>x.id===id?obj:x);else state.events.push(obj);closeModal();save(old?'Actuación actualizada':'Nueva actuación guardada');setPage('actuaciones');return}
 if(e.target.id==='marchForm'){e.preventDefault();const f=new FormData(e.target);const id=f.get('marchId');const name=String(f.get('name')||'').trim();if(!name)return;if(state.repertoire.some(m=>bmmTitleKey(m.name)===bmmTitleKey(name)&&m.id!==id)){showToast('Ya existe una marcha con ese nombre.',true);return}const obj={id:id||uid('march'),name,author:String(f.get('author')||'').trim(),style:String(f.get('style')||'').trim()};if(id)state.repertoire=state.repertoire.map(m=>m.id===id?obj:m);else state.repertoire.push(obj);closeModal();save(id?'Marcha actualizada':'Marcha añadida al repertorio');setPage('repertorio');return}
 if(e.target.id==='categoryForm'){e.preventDefault();const inp=document.getElementById('newCategory');const val=inp.value.trim();if(val&&!state.categories.some(c=>c.toLocaleLowerCase('es')===val.toLocaleLowerCase('es'))){state.categories.push(val);save('Categoría añadida');}else if(val){showToast('Esa categoría ya existe.',true)}return}
});
document.getElementById('content').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)setPage(b.dataset.page)});
document.addEventListener('change',async e=>{if(e.target.id!=='importFile')return;const file=e.target.files?.[0];if(!file)return;try{const x=JSON.parse(await file.text());if(!Array.isArray(x.repertoire)||!Array.isArray(x.events))throw new Error('Formato no válido');if(confirm(`La copia contiene ${x.repertoire.length} marchas y ${x.events.length} actuaciones. Reemplazará los datos actuales. ¿Importar?`)){state=normalize(x);save('Copia importada correctamente');setPage('dashboard')}}catch(err){showToast('No se ha podido importar: el archivo no es una copia válida.',true)}finally{e.target.value=''}});
render();
